import 'dart:convert';

import 'package:flutter/services.dart';

/// Resolves contract ids (backdrop, actor + expression, prop) to bundled asset paths.
/// Source of truth: assets/nova/manifest.json (generated by tools/process_assets.py).
/// Nothing here throws on unknown ids: it returns a safe fallback or null.
class NovaAssets {
  NovaAssets(Map<String, dynamic> manifest)
      : _manifest = manifest,
        _fileById = <String, String>{} {
    final assets = manifest['assets'];
    if (assets is List) {
      for (final a in assets) {
        if (a is Map && a['id'] is String && a['file'] is String) {
          _fileById[a['id'] as String] = a['file'] as String;
        }
      }
    }
  }

  static const String root = 'assets/nova';

  final Map<String, dynamic> _manifest;
  final Map<String, String> _fileById;

  static Future<NovaAssets> load([AssetBundle? bundle]) async {
    final b = bundle ?? rootBundle;
    final s = await b.loadString('$root/manifest.json');
    return NovaAssets.fromJsonString(s);
  }

  factory NovaAssets.fromJsonString(String s) =>
      NovaAssets(Map<String, dynamic>.from(jsonDecode(s) as Map));

  Map<String, dynamic> get _actors {
    final a = _manifest['actors'];
    return a is Map ? Map<String, dynamic>.from(a) : <String, dynamic>{};
  }

  String? _path(String id) {
    final f = _fileById[id];
    return f == null ? null : '$root/$f';
  }

  /// Full-bleed backdrop. Unknown ids fall back to the first known backdrop.
  String? backdropPath(String id) {
    final p = _path(id);
    if (p != null) return p;
    final list = _manifest['backdrops'];
    if (list is List && list.isNotEmpty) return _path(list.first as String);
    return null;
  }

  bool isKnownActor(String actorId) => _actors.containsKey(actorId);

  /// Pose name for [actorId] showing [expression]; falls back to the first available pose.
  String? poseFor(String actorId, String? expression) {
    final a = _actors[actorId];
    if (a is! Map) return null;
    final poses = (a['poses'] is List) ? List<String>.from(a['poses'] as List) : <String>[];
    if (poses.isEmpty) return null;
    final map = a['pose_map'] is Map ? Map<String, dynamic>.from(a['pose_map'] as Map) : <String, dynamic>{};
    final pose = map[expression ?? 'idle'];
    if (pose is String && poses.contains(pose)) return pose;
    return poses.contains('standing') ? 'standing' : poses.first;
  }

  /// Image for an actor in a given expression (null if the actor is unknown).
  String? actorPath(String actorId, String? expression) {
    final pose = poseFor(actorId, expression);
    if (pose == null) return null;
    return _path('${actorId}_$pose');
  }

  /// Props use their full id (e.g. prop_coin_gold, animal_fish_smiling).
  String? propPath(String id) => _path(id);
}
